def norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))
def comps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                out.append((col,cells))
    return out
def transform(g):
    g=[row[:] for row in g]; cs=comps(g); groups={}
    for col,cells in cs: groups.setdefault(norm(cells),[]).append((col,cells))
    for shp,lst in groups.items():
        if len(lst)>1:
            tgt=max(c for c,_ in lst)
            for col,cells in lst:
                for y,x in cells: g[y][x]=tgt
    return g
